ALLOWED = {'DETECTED': 'TRIAGED', 'TRIAGED': 'CONTAINED', 'CONTAINED': 'ERADICATED', 'ERADICATED': 'RECOVERING', 'RECOVERING': 'RESOLVED', 'RESOLVED': 'REVIEWED'}
def transition(incident, next_state, evidence):
    if ALLOWED.get(incident.status) != next_state:
        raise ValueError('INVALID_TRANSITION')
    if next_state in {'CONTAINED', 'RESOLVED'} and not evidence:
        raise ValueError('EVIDENCE_REQUIRED')
    incident.status = next_state
    return incident
